<?php
namespace App\Http\Controllers\Api; use App\Http\Controllers\Controller; use App\Http\Resources\DepartmentResource; use App\Models\Department; use App\Services\AuditLogService; use Illuminate\Http\Request; use Illuminate\Http\Resources\Json\AnonymousResourceCollection; use Illuminate\Http\Response;
class DepartmentController extends Controller { public function index(Request $r): AnonymousResourceCollection { return DepartmentResource::collection(Department::with('parent')->orderBy('name')->paginate($r->integer('per_page')?:100)); } public function store(Request $r): DepartmentResource { abort_unless($r->user()->hasPermission('hr.departments.manage'),403); $d=Department::create($this->data($r)); AuditLogService::log('hr','department_created',$d,null,$d->toArray(),$r); return new DepartmentResource($d); } public function update(Request $r, Department $department): DepartmentResource { abort_unless($r->user()->hasPermission('hr.departments.manage'),403); $old=$department->toArray(); $department->update($this->data($r,$department)); AuditLogService::log('hr','department_updated',$department,$old,$department->toArray(),$r); return new DepartmentResource($department); } public function destroy(Request $r, Department $department): Response { abort_unless($r->user()->hasPermission('hr.departments.manage'),403); $department->delete(); return response()->noContent(); } private function data(Request $r, ?Department $d=null): array { return $r->validate(['code'=>['required','string','max:100','unique:departments,code'.($d?','.$d->id:'')],'name'=>['required','string','max:255'],'parent_id'=>['nullable','exists:departments,id'],'type'=>['nullable','string','max:100'],'head_employee_id'=>['nullable','exists:employees,id'],'is_active'=>['boolean']]); } }
